import { PinInterface } from '~/entities/pin/ui/pin-interface';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

export const usePinBottomSheet = () => {
  const openPinBottomSheet = (onComplete: (close: () => void) => void) => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <BottomSheet afterLeave={unmount} open={isOpen} onClose={close} preventCloseOnOutsideClick>
          <div className="h-[85vh]">
            <PinInterface
              type={PinInteractionMode.인증_바텀시트}
              title={i18n.t('pin:titleInputPin')}
              message={i18n.t('pin:messageInputPin')}
              step={1}
              prevPin={''}
              pin={''}
              isError={false}
              handleCompleteInput={() => {
                onComplete?.(close);
              }}
            />
          </div>
        </BottomSheet>
      );
    });
  };

  return { openPinBottomSheet };
};
